insert into public.chok_laws (id,name,name_en,domain,definition,mechanism,examples,evidence_strength,correlations,source,created_by,tags) values
('peto-paradox','פרדוקס פטו','Peto''s Paradox',array['ביולוגיה']::text[],'גופים גדולים אינם לוקים בסרטן יותר מגופים קטנים, למרות שיש להם פי מיליון תאים יותר ולכן הרבה יותר הזדמנויות למוטציה סרטנית.','ברירה טבעית יצרה מנגנוני הגנה מדורגים בגופים גדולים. פילים למשל מחזיקים 20 עותקים של גן TP53 (לאדם יש 2). ככל שהגוף גדול יותר, כך פתח ה"התפתחות ונגד סרטן" גדול יותר.','[{"domain":"ביולוגיה","description":"לוויתן ענק (150 טון) חולה פחות בסרטן מאדם (70 ק\"ג) לאורך חייו"},{"domain":"חברה","description":"ארגונים גדולים מפתחים מנגנוני בקרה מורכבים יותר מסטארטאפים קטנים"},{"domain":"עיר","description":"ערים גדולות מפתחות מערכות ניקוז, בטיחות ובריאות חזקות יותר מכפרים"}]'::jsonb,5,array['naked-mole-rat-law','dunbar-number','zipf-law']::text[],'Epoch 409, ספטמבר 2026','system',array['סרטן','אבולוציה','גודל','הגנה']::text[]),
('naked-mole-rat-law','חוק חולד העיוור','Naked Mole Rat Cancer Immunity',array['ביולוגיה']::text[],'חולד העיוור חסין לסרטן לכל אורך חייו (30 שנה — פי 10 מחולד רגיל), ממשיך לתפקד עד לרגע מותו ללא ירידה תפקודית.','תאי חולד העיוור מחוסנים על ידי חומר בשם היאלורונן בצפיפות גבוהה מאוד המונע את התפשטותם. כשתאים מתחילים להתנהג "בצורה סרטנית" — שכניהם מחנקים אותם. זהו מנגנון חנק חברתי בין-תאי.','[{"domain":"ביולוגיה","description":"תאי חולד עיוור מפסיקים להתחלק כשמרגישים צפיפות — אנטי-תפשטות מובנה"},{"domain":"חברה","description":"קהילות קטנות ואינטימיות מאתרות ומגיבות לסטייה חברתית מהר יותר מחברה אנונימית"},{"domain":"תרבות","description":"מסורות תרבותיות חזקות פועלות כמנגנון חנק על רעיונות הרסניים"}]'::jsonb,5,array['peto-paradox','dunbar-number','social-contagion']::text[],'Epoch 409, ספטמבר 2026','system',array['אריכות ימים','סרטן','חסינות','קהילה']::text[]),
('human-performance-ceiling','חוק תקרת הביצועים האנושיים','Human Performance Ceiling',array['ספורט','ביולוגיה']::text[],'שיאים עולמיים בביצועים גופניים מתכנסים לתקרה ביולוגית. קצב השיפור קטן בהדרגה ומתכנס לגבול פיזיולוגי.','הגוף האנושי מוגבל על ידי מהירות הולכה עצבית, יעילות צריכת חמצן ומתח שרירי מרבי. שיפור אימוני יכול להתקרב לגבול אך לא לעבור אותו.','[{"domain":"ספורט","description":"ריצת 100 מ'' — השיא התכנס מ-10.6 שניות (1912) ל-9.58 (2009). מודלים מחשבים מינימום ~9.44"},{"domain":"כלכלה","description":"פריון עבודה: חוק התשואה השולית הפוחתת — כל יחידת השקעה נוספת מוסיפה פחות מהקודמת"},{"domain":"תרבות","description":"לימוד שפה: 80% שליטה עולה 20% מהמאמץ; 20% האחרונים עולים 80%"}]'::jsonb,4,array['diminishing-returns','pareto-principle','skill-transfer']::text[],'Epoch 409, ספטמבר 2026','system',array['ביצועים','גבולות','שיאים','ביולוגיה']::text[]),
('skill-transfer','חוק העברת מיומנות','Skill Transfer Law',array['ספורט','חברה']::text[],'מיומנות גבוהה בתחום אחד מעבירה יתרון מובנה לתחומים קרובים, בגלל מנגנוני תיאום ועיבוד מרכזיים משותפים.','אימון ברמה גבוהה מפתח מנגנוני שליטה עצביים כלליים (ריכוז, זמן תגובה, זיהוי דפוסים) שמועברים מתחום לתחום.','[{"domain":"ספורט","description":"מייקל ג''ורדן — ביסבול לאחר NBA; ספורטאים עם כישורי קואורדינציה מצטיינים בספורטים מרובים"},{"domain":"חברה","description":"מנהיג טוב בתחום אחד לרוב מתאים לתפקידי מנהיגות בתחומים שונים"},{"domain":"תרבות","description":"מוזיקאים לרוב מצטיינים גם במתמטיקה — מנגנון זיהוי דפוסים משותף"}]'::jsonb,3,array['human-performance-ceiling','dunbar-number']::text[],'Epoch 409, ספטמבר 2026','system',array['מיומנות','למידה','העברה','ספורט']::text[]),
('information-cascade','חוק קסקדת המידע','Information Cascade',array['חברה']::text[],'בקסקדה חברתית, אנשים מאוחרים מקבלים החלטות בהתבסס על ה"אות הציבורי" של מה שאחרים עשו — ומתעלמים ממידע פרטי שלהם. התוצאה: ההחלטה של המוקדמים שולטת בכולם.','כשאינפורמציה של קודמים עולה על אינפורמציה פרטית, ההחלטה הרציונלית היא להתעלם מהמידע שלך ולחקות. זה יוצר קסקדה שיכולה להתרסק כשנחשף שהמידע הציבורי היה שגוי.','[{"domain":"חברה","description":"בחירת מסעדה: אנשים נכנסים לצפופה כי \"כולם שם\" — למרות שהמסעדה הריקה טובה יותר"},{"domain":"כלכלה","description":"בועות פיננסיות: משקיעים קונים כי \"כולם קונים\" — גם כשהמספרים לא מצדיקים"},{"domain":"תרבות","description":"ספר רב-מכר: כשמספיק אנשים קוראים אותו, שאר הרוכשים קונים בגלל הפופולריות"}]'::jsonb,5,array['schelling-point','social-contagion','minority-rule']::text[],'Epoch 409, ספטמבר 2026','system',array['החלטות','קבוצה','אות','מידע']::text[]),
('schelling-point','נקודת השלינג','Schelling Point',array['חברה','כלכלה']::text[],'ללא תקשורת, קבוצות עצמאיות מתכנסות לנקודות מוקד טבעיות — מקום, שעה, ברירת מחדל — שמרגישות "ברורות מאליהן" ומהוות פתרון קואורדינציה.','כשקואורדינציה נדרשת ותקשורת לא אפשרית, אנשים בוחרים את המובן מאליו — הסמטרי, הפשוט, הצפוי. זה יוצר שיווי משקל ללא הסכמה מפורשת.','[{"domain":"חברה","description":"\"נפגש בכיכר המרכזית בחצות\" — ללא שיחה, שתי קבוצות יתכנסו לשם"},{"domain":"כלכלה","description":"עגול: אנשים מציעים מחיר עגול ($100 לא $97) גם בלי תיאום"},{"domain":"עיר","description":"כיכרות ומוקדים עירוניים פועלים כנקודות שלינג — מקום טבעי למפגש ללא תיאום"}]'::jsonb,5,array['information-cascade','murmuration-law','dunbar-number']::text[],'Epoch 409, ספטמבר 2026','system',array['קואורדינציה','מוקד','ציפיות','שיווי משקל']::text[]),
('social-contagion','חוק ההדבקה החברתית','Social Contagion Law',array['חברה']::text[],'התנהגויות, רגשות ורעיונות מתפשטים בחברה כמחלות: יש ל"נשא", סף הדבקה, מרחק חברתי ומעל סף קריטי — התפשטות אקספוננציאלית.','כשמספיק אנשים קרובים מאמצים התנהגות, העלות החברתית של אי-אימוץ עולה. מתחת לסף — ההתנהגות דועכת. מעליו — פוצצת.','[{"domain":"חברה","description":"אופנת לבוש: כשמספר קריטי בקבוצה אימצה סגנון — שאר הקבוצה מאמצת"},{"domain":"תרבות","description":"מחאה: תנועה חברתית מתפוצצת רק לאחר שמספיק אנשים מוכנים \"להיות ראשון\""},{"domain":"כלכלה","description":"אימוץ טכנולוגיה: טלפון, SMS, WhatsApp — כל אחד פוצץ לאחר אחוז קריטי של משתמשים"}]'::jsonb,5,array['minority-rule','information-cascade','wave-law']::text[],'Epoch 409, ספטמבר 2026','system',array['התפשטות','נורמות','רשת','סף']::text[]),
('minority-rule','חוק המיעוט הנחוש','Minority Rule',array['חברה']::text[],'מיעוט של ~25% עם דעה עקבית, בלתי-פשרנית ומוצגת בביטחון — יכול להפוך לדעת הרוב. לא הרוב קובע, אלא הנחישות.','רוב רך (60%) שאינו מחויב להתנגד, ייסוג מול מיעוט נחוש (25%) שמסרב להתפשר. במשא ומתן ובקבלת החלטות — הנחישות גוברת על המספרים.','[{"domain":"חברה","description":"אנשים עם אלרגיות קבעו את תקני המזון של כל הציבור — מיעוט נחוש ביסס נורמות חדשות"},{"domain":"תרבות","description":"מהפכות תרבותיות — פמיניזם, זכויות אזרח — לא התחילו ברוב, אלא במיעוט נחוש"},{"domain":"כלכלה","description":"רגולציות פיננסיות: מיעוט פעיל של לובייסטים עיצב חוקים שחלים על כולם"}]'::jsonb,4,array['social-contagion','information-cascade','schelling-point']::text[],'Epoch 409, ספטמבר 2026','system',array['מיעוט','נחישות','שינוי','כוח']::text[]),
('murmuration-law','חוק הלהקה (מורמורציה)','Murmuration Law',array['ביולוגיה','חברה']::text[],'כל פרט עוקב אחר 7 שכנים קרובים בלבד. תנועה קולקטיבית מורכבת, יפה ויעילה נוצרת מכלל מקומי פשוט — ללא מנהיג מרכזי.','ביצוע חוקים מקומיים פשוטים (מרחק, מהירות, כיוון) יוצר דפוסים גלובליים מורכבים. הגדלה עצמית של המערכת בלי תכנון מרכזי.','[{"domain":"ביולוגיה","description":"עדרי ציפורים זרזיר — מאות אלפי ציפורים נעות כגוף אחד ללא מוביל"},{"domain":"חברה","description":"שוק חופשי: מחירים נקבעים מהחלטות מקומיות של מיליוני קונים ומוכרים"},{"domain":"עיר","description":"תנועה עירונית: כשכל נהג מגיב רק לשכניו הקרובים — נוצרים גלי פקקים שנעים כגל"}]'::jsonb,5,array['wave-law','schelling-point','social-contagion']::text[],'Epoch 409, ספטמבר 2026','system',array['עדר','אינטליגנציה קולקטיבית','ביזור','כלל פשוט']::text[]),
('wave-law','חוק הגל האנושי','Stadium Wave Law',array['חברה','ספורט']::text[],'גל אצטדיון נוצר רק כשקבוצה של ~25-30 אנשים קמים בו-זמנית. פחות מזה — הגל מת. יותר מזה — הגל מתפשט בלתי-ניתן לעצירה.','קיים סף קריטי להצתת גל. מתחת לסף — ללא מסה קריטית, הפעולה לא מתפשטת. מעל הסף — גל עצמאי נוצר ממשיך ללא צורך בקיום הקבוצה המקורית.','[{"domain":"ספורט","description":"אצטדיון כדורגל — ניתן לצפות ולחשב בדיוק כמה אנשים נדרשים להתחיל גל"},{"domain":"חברה","description":"מחיאות כפיים של קהל — הופך לריתמי ומסונכרן ספונטנית לאחר מסה קריטית"},{"domain":"כלכלה","description":"עסק חדש: קריסה מתחת ל-X לקוחות; התפשטות אקספוננציאלית מעליו"}]'::jsonb,4,array['murmuration-law','social-contagion','minority-rule']::text[],'Epoch 409, ספטמבר 2026','system',array['סף','גל','המון','התפשטות']::text[]),
('adaptive-sleep-law','חוק השינה הקבוצתית','Group Sleep Coordination',array['ביולוגיה','חברה']::text[],'ביצורים חברתיים, שינה מתואמת בצורה שתמיד נותרת לפחות אחד ערני. לא מוסכמת — נוצרת ספונטנית מחוקים מקומיים של כל פרט.','כל פרט נרדם כשמספיק שכנים ערים. ספוג שינה מצטבר דוחף לשינה. מנגנון זה יוצר שמירה מחזורית ללא תיאום.','[{"domain":"ביולוגיה","description":"דולפינים — מחצית המוח ישנה בכל פעם; להקות ציפורים — לסירוגין"},{"domain":"חברה","description":"כוננות רפואית: רופאי חדר מיון עובדים ברוטציה כך שתמיד יש כיסוי"},{"domain":"עיר","description":"עיר שלא ישנה: שכונות מסחריות ופנאי מחולקות בזמן כך שהעיר תמיד פעילה"}]'::jsonb,4,array['murmuration-law','dunbar-number']::text[],'Epoch 409, ספטמבר 2026','system',array['שינה','שמירה','קהילה','ביזור']::text[]),
('diminishing-returns','חוק התשואה השולית הפוחתת','Law of Diminishing Marginal Returns',array['כלכלה','ספורט','ביולוגיה']::text[],'כשמוסיפים עוד ועוד מגורם אחד (עבודה, אימון, השקעה) תוך שמירה על שאר הגורמים קבועים — כל יחידה נוספת מוסיפה פחות מהקודמת.','משאבים משלימים הופכים לצוואר בקבוק. יעילות מרגינלית יורדת כשאתה מגיע לגבול הגורם המגביל.','[{"domain":"ספורט","description":"אימון: שעה ראשונה מוסיפה הרבה; שעה 10 ביום — כמעט כלום ואף פוגעת"},{"domain":"כלכלה","description":"פרסום: כל הוצאת שקל נוספת על אותה פרסומת מכניסה פחות לקוחות"},{"domain":"ביולוגיה","description":"מינון תרופה: הגדלת מינון מביאה פחות ופחות תועלת — ואז רעילות"}]'::jsonb,5,array['human-performance-ceiling','pareto-principle']::text[],'קלאסי — David Ricardo (1817)','system',array['כלכלה','ייצור','אופטימיזציה','גבולות']::text[]),
('dunbar-number','מספר דנבר','Dunbar''s Number',array['חברה','ביולוגיה']::text[],'המוח האנושי מסוגל לנהל מערכות יחסים אמיתיות ויציבות עם לא יותר מ-150 אנשים בו-זמנית. זהו הגבול הקוגניטיבי לקהילה אנושית יציבה.','נאו-קורטקס אנושי מוגבל בעיבוד מורכבות חברתית. מנגנון ריצה עצבית של "מה אחרים חושבים" מוגבל ל-150.','[{"domain":"חברה","description":"כפרים מסורתיים ברחבי העולם: ממוצע ~150 נפש — גודל \"טבעי\" של קהילה מתפקדת"},{"domain":"כלכלה","description":"Gore-Tex: גייס לא יותר מ-150 עובדים לכל מפעל — גדול יותר = ביורוקרטיה"},{"domain":"עיר","description":"שכונות אורגניות: השכנות האמיתית (לדעת שמות) מוגבלת ל-100-150 משפחות"}]'::jsonb,4,array['naked-mole-rat-law','murmuration-law','schelling-point']::text[],'Robin Dunbar (1992), ''Neocortex size as a constraint on group size''','system',array['קהילה','קוגניציה','גודל','חברה']::text[]),
('pareto-principle','עקרון פארטו','Pareto Principle (80/20)',array['כלכלה','חברה']::text[],'ב-80% מהמקרים, 20% מהסיבות מייצרות 80% מהתוצאות. התפלגות שאינה אחידה — מיעוט של גורמים מייצר רוב ההשפעה.','חוק חזקה (Power Law): בחלוקה לא-אחידה, ההתפלגות מצייתת לחוק חזקה ולא לנורמל. מה שמוביל מוביל הרבה יותר.','[{"domain":"כלכלה","description":"20% מהלקוחות מייצרים 80% מהרווח; 20% מהמוצרים = 80% מהמכירות"},{"domain":"חברה","description":"20% מהכבישים סופגים 80% מהתנועה; 20% מהאנשים מייצרים 80% מהתוכן ברשת"},{"domain":"ביולוגיה","description":"20% מהמינים מייצרים 80% מהביומסה באקוסיסטם"}]'::jsonb,5,array['diminishing-returns','zipf-law','minority-rule']::text[],'Vilfredo Pareto (1896)','system',array['80/20','התפלגות','יעילות','כוח']::text[]),
('zipf-law','חוק זיפ','Zipf''s Law',array['תרבות','עיר','ביולוגיה']::text[],'המילה השנייה הנפוצה ביותר בשפה מופיעה בחצי מתדירות הראשונה. השלישית — בשליש. ברשימות רבות בטבע ובתרבות — הדירוג n מופיע 1/n פעמים.','מינימיזציה סימולטנית של מאמץ הדובר ומאמץ השומע. הוצג גם בגדלי ערים, עושר, חברות, מין — בטבע ובחברה.','[{"domain":"תרבות","description":"בעברית: \"של\" מופיעה פי 2 יותר מהמילה השנייה, פי 3 יותר מהשלישית"},{"domain":"עיר","description":"ערי ישראל: תל אביב > חיפה > ירושלים ביחס קרוב ל-1:0.5:0.33 לפי היסטוריה"},{"domain":"כלכלה","description":"חברות: ענקיות כמו Apple שוות פי 2 מהשנייה, פי 3 מהשלישית"}]'::jsonb,5,array['pareto-principle','peto-paradox']::text[],'George Kingsley Zipf (1949), ''Human Behavior and the Principle of Least Effort''','system',array['שפה','התפלגות','ערים','חזקה']::text[]),
('conways-law','חוק קונווי','Conway''s Law',array['תרבות','כלכלה']::text[],'ארגונים תמיד מייצרים מערכות שמשקפות את מבנה התקשורת הפנים-ארגוני שלהם. עיצוב מוצר = מפת הארגון.','מה שנמצא בגבולות הארגון (טיפול קל) יצוף לממשקים; מה שחוצה גבולות (טיפול קשה) יישאר רופף.','[{"domain":"תרבות","description":"מערכות תוכנה עם 3 צוותים — לרוב מייצרות אדריכלות עם 3 שכבות"},{"domain":"עיר","description":"עיר שמוניציפליות שלה מחולקת למחלקות — יוצרת אזורי עיר המשקפים את המחלקות"},{"domain":"כלכלה","description":"בנק עם מחלקת פרסום נפרדת — יוצר מוצרים שמרגישים \"שווק\" ולא \"תוכנן\""}]'::jsonb,4,array['dunbar-number','murmuration-law']::text[],'Melvin Conway (1968)','system',array['ארגון','עיצוב','מבנה','מוצר']::text[]),
('metcalfe-law','חוק מטקאלף','Metcalfe''s Law',array['כלכלה','חברה']::text[],'ערך רשת גדל בריבוע מספר המשתמשים. 10 משתמשים = 100 ערך; 100 משתמשים = 10,000 ערך. ההצטרפות של כל משתמש נוסף מועילה לכל הקיימים.','כל זוג חדש של משתמשים = קשר תקשורת חדש. מספר הקשרים = n*(n-1)/2 ≈ n².','[{"domain":"כלכלה","description":"WhatsApp: ערך אפסי ל-1 משתמש; ערך אדיר ל-2 מיליארד"},{"domain":"חברה","description":"שפה: ערך שפה גדל עם מספר הדוברים — ולכן אנגלית שווה יותר משוודית"},{"domain":"עיר","description":"תחבורה ציבורית: כל תחנה חדשה מוסיפה ערך לכל התחנות הקיימות"}]'::jsonb,4,array['social-contagion','wave-law','pareto-principle']::text[],'Robert Metcalfe (1980), ''Ethernet''','system',array['רשת','ערך','אפקט רשת','צמיחה']::text[]),
('brooks-law','חוק ברוקס','Brooks'' Law',array['תרבות','כלכלה']::text[],'הוספת כוח אדם לפרויקט מאחר — מאחרת אותו עוד יותר. תקשורת גדלה כריבוע; הכנסת אנשים חדשים עולה זמן הדרכה ותיאום.','כל עובד חדש = n קשרי תקשורת חדשים עם כל הקיימים. מתחת לסף קריטי — עלות גבוהה מהתועלת.','[{"domain":"תרבות","description":"פרויקטי תוכנה: IBM OS/360 — הוספת מתכנתים כשל בפרויקט רק הכפילה את העיכוב"},{"domain":"כלכלה","description":"בניית בניין: 2x פועלים לא = 2x מהירות — יש תיאום שמוגבל פיזית"},{"domain":"חברה","description":"ועדות גדולות: יותר חברים = פחות החלטות. לאחר מספר מסוים — פרלמנט"}]'::jsonb,4,array['dunbar-number','conways-law','diminishing-returns']::text[],'Fred Brooks (1975), ''The Mythical Man-Month''','system',array['פרויקט','ניהול','תיאום','עיכוב']::text[]),
('goodhart-law','חוק גודהארט','Goodhart''s Law',array['כלכלה','חברה']::text[],'כשמדד הופך למטרה — הוא מפסיק להיות מדד טוב. ניסיון למקסם מדד גורם לעיוות שלו ולאיבוד הקשר עם מה שנועד למדוד.','כשיש תמריצים על מדד ספציפי, אנשים מאופטמים למדד ולא למה שהוא מייצג. עיוות פוגע בתוקף המדד.','[{"domain":"כלכלה","description":"מדד ביצועים: כשמשלמים לרופאים לפי מספר ביקורים — מספר הביקורים עולה, לא הבריאות"},{"domain":"חברה","description":"ציון בגרות: כשהוא מטרה עצמאית — תלמידים ממקסמים ציון, לא ידע"},{"domain":"עיר","description":"מדדי \"שיעור פשע\" — ערים מדווחות פחות פשעים כדי להיראות טוב"}]'::jsonb,5,array['information-cascade','conways-law']::text[],'Charles Goodhart (1975)','system',array['מדדים','תמריצים','עיוות','ניהול']::text[]),
('hebbs-law','חוק הב','Hebb''s Law',array['ביולוגיה','תרבות']::text[],'נוירונים שיורים יחד — מתחברים יחד. כל חזרה מחזקת את הקשר העצבי. למידה = הידוק קשרים; שכחה = הרפיתם.','פלסטיות סינפטית: חיזוק LTP של סינפסות שהופעלו בו-זמנית. ביולוגיה של הרגל, מיומנות וטראומה.','[{"domain":"ביולוגיה","description":"לימוד נגינה: כל חזרה מחזקת נתיב עצבי; הקשר בין אצבע לצליל מתהדק"},{"domain":"תרבות","description":"הרגלים תרבותיים: חזרה על פולחן, שיר, סיפור — מחזקת את \"הנתיב\" הקבוצתי"},{"domain":"חברה","description":"אמונות: ככל שחוזרים עליהן יותר (תקשורת, חינוך) — כך חוזקן גדל בלי קשר לאמיתות"}]'::jsonb,5,array['skill-transfer','social-contagion']::text[],'Donald Hebb (1949)','system',array['למידה','מוח','הרגל','פלסטיות']::text[]),
('braess-paradox','פרדוקס בראס','Braess''s Paradox',array['עיר','כלכלה']::text[],'הוספת כביש לרשת עמוסה יכולה להאריך את זמן הנסיעה של כולם, וסגירת כביש יכולה לקצר אותו.','כל נהג בוחר את המסלול הטוב לעצמו. קיצור דרך חדש מושך את כולם לאותו מקטע, ושיווי המשקל החדש גרוע מהקודם. טובת הפרט וטובת הרשת נפרדות.','[{"domain":"עיר","description":"סיאול פירקה את הכביש המהיר שמעל נחל צ''ונגייצ''ון ושיקמה את הנחל, והתנועה במרכז העיר לא קרסה"},{"domain":"ספורט","description":"קבוצת כדורסל שמעבירה כל התקפה דרך הכוכב שלה נעשית צפויה, ולעתים קולעת פחות"},{"domain":"כלכלה","description":"ערוץ מסחר מהיר חדש מושך את כל הסוחרים לאותו נתיב, והעומס מוחק את היתרון"}]'::jsonb,4,array['induced-demand','tragedy-of-commons','schelling-point']::text[],'Dietrich Braess (1968)','system',array['תנועה','רשת','שיווי משקל','כבישים']::text[]),
('induced-demand','חוק הביקוש המושרה','Induced Demand',array['עיר','כלכלה']::text[],'הרחבת כביש עמוס מייצרת נסיעות חדשות, עד שהעומס חוזר לרמתו הקודמת.','נתיב נוסף מוזיל את מחיר הנסיעה בזמן. אנשים שנמנעו מלנסוע, נסעו בשעה אחרת או באמצעי אחר, חוזרים לכביש. ההיצע יוצר את הביקוש שלו.','[{"domain":"עיר","description":"מחקר על ערי ארצות הברית מצא שהנסועה גדלה כמעט ביחס של אחד לאחד עם תוספת הנתיבים"},{"domain":"כלכלה","description":"דיסק גדול יותר מתמלא, ותיבת דואר מהירה יותר מתמלאת בעוד הודעות"},{"domain":"חברה","description":"הוספת שעות קבלה מזמינה פניות שלא היו מגיעות קודם"}]'::jsonb,4,array['braess-paradox','parkinson-law','marchetti-constant']::text[],'Anthony Downs (1962); Duranton & Turner (2011)','system',array['תנועה','כבישים','ביקוש','תכנון']::text[]),
('eyes-on-the-street','חוק העיניים על הרחוב','Eyes on the Street',array['עיר','חברה']::text[],'רחוב בטוח הוא רחוב שיש בו אנשים שמביטים בו: חזיתות פעילות, חלונות ותנועה רגלית לאורך היום.','נוכחות רציפה של עוברים ושבים ושל בעלי עסקים יוצרת השגחה טבעית, בלי שוטר ובלי מצלמה. עירוב שימושים מאריך את שעות הפעילות, ולכן את שעות ההשגחה.','[{"domain":"עיר","description":"רחוב מסחרי עם דירות מעל החנויות חי גם בערב, לעומת רחוב משרדים שמתרוקן בחמש"},{"domain":"חברה","description":"חצר משותפת שהחלונות פונים אליה מאפשרת לילדים לשחק לבד"},{"domain":"ביולוגיה","description":"בלהקה, ריבוי עיניים מקצר את זמן הגילוי של טורף"}]'::jsonb,3,array['broken-windows','murmuration-law','adaptive-sleep-law']::text[],'Jane Jacobs (1961), ''The Death and Life of Great American Cities''','system',array['רחוב','ביטחון','עירוב שימושים','הליכה']::text[]),
('marchetti-constant','קבוע מרקטי','Marchetti''s Constant',array['עיר','חברה']::text[],'בני אדם מקדישים לנסיעות יומיות כשעה ביום, בכל תקופה ובכל אמצעי תחבורה.','תקציב הזמן קבוע, והמהירות משתנה. לכן אמצעי תחבורה מהיר יותר לא מקצר את היומיום, אלא מגדיל את העיר: רדיוס העיר שווה למרחק של כחצי שעה.','[{"domain":"עיר","description":"עיר של הולכי רגל הייתה ברדיוס של כשניים וחצי קילומטרים; הרכבת והמכונית הרחיבו אותה פי כמה"},{"domain":"חברה","description":"רכבת מהירה לא מקצרת את זמן היוממות, אלא מרחיקה את מקום המגורים"},{"domain":"כלכלה","description":"מחיר הדירה יורד עם זמן ההגעה למרכז, ולא עם המרחק בקילומטרים"}]'::jsonb,3,array['induced-demand','urban-scaling','dunbar-number']::text[],'Cesare Marchetti (1994), על בסיס Yacov Zahavi','system',array['יוממות','זמן','גודל עיר','תחבורה']::text[]),
('urban-scaling','חוק הסקיילינג העירוני','Urban Scaling Law',array['עיר','כלכלה','ביולוגיה']::text[],'כשעיר מכפילה את אוכלוסייתה, התוצר, החדשנות וגם הפשיעה גדלים בכ-15% יותר מפי שניים, והתשתית הנדרשת קטנה בכ-15%.','עיר היא רשת של מפגשים. צפיפות מגדילה את מספר המפגשים לאדם, ולכן את קצב ההמצאה, ההכנסה וגם המחלות. התשתית, כמו כלי דם, מתייעלת עם הגודל.','[{"domain":"עיר","description":"מספר הפטנטים והשכר הממוצע עולים עם גודל העיר, וכך גם קצב ההליכה"},{"domain":"ביולוגיה","description":"בעלי חיים גדולים חסכוניים יותר באנרגיה לכל קילוגרם, כפי שעיר גדולה חסכונית בכבישים לנפש"},{"domain":"כלכלה","description":"חברות, בשונה מערים, גדלות בקצב שהולך ומאט, ולכן רובן מתות"}]'::jsonb,4,array['kleiber-law','zipf-law','metcalfe-law','marchetti-constant']::text[],'Bettencourt, Lobo, Helbing, Kühnert & West (2007), PNAS','system',array['גודל עיר','חדשנות','צפיפות','רשת']::text[]),
('kleiber-law','חוק קלייבר','Kleiber''s Law',array['ביולוגיה']::text[],'קצב חילוף החומרים של בעל חיים גדל עם מסת הגוף בחזקת שלושה רבעים: גוף גדול פי 16 צורך אנרגיה רק פי 8.','רשתות הובלה מסועפות, כמו כלי דם, מתייעלות עם הגודל. לכן בעלי חיים גדולים חיים לאט יותר: דופק איטי, גדילה איטית וחיים ארוכים.','[{"domain":"ביולוגיה","description":"לב של עכבר פועם כ-600 פעמים בדקה, ולב של פיל כ-30"},{"domain":"עיר","description":"עיר גדולה צריכה פחות תחנות דלק וקילומטרים של צנרת לכל תושב"},{"domain":"כלכלה","description":"יתרון לגודל: עלות ליחידה יורדת כשהרשת גדלה"}]'::jsonb,5,array['urban-scaling','peto-paradox','diminishing-returns']::text[],'Max Kleiber (1932)','system',array['אנרגיה','גודל','רשת','חילוף חומרים']::text[]),
('tragedy-of-commons','הטרגדיה של נחלת הכלל','Tragedy of the Commons',array['כלכלה','חברה','עיר']::text[],'משאב משותף שכל אחד מנצל לטובתו נשחק עד שהוא אובד לכולם.','הרווח מניצול נוסף שייך ליחיד, והמחיר מתחלק בין כולם. בלי כללים, בעלות או נורמה קהילתית, ההיגיון של כל פרט מוביל להרס משותף.','[{"domain":"עיר","description":"חניה חינם ברחוב מתמלאת, והחיפוש אחריה מוסיף תנועה לכל הרחוב"},{"domain":"ביולוגיה","description":"דיג יתר: כל ספינה מרוויחה מעוד רשת, עד שהלהקה קורסת"},{"domain":"חברה","description":"קהילות שמנהלות יחד מים או מרעה לאורך דורות מראות שכללים מקומיים מונעים את הטרגדיה"}]'::jsonb,4,array['braess-paradox','goodhart-law','minority-rule']::text[],'Garrett Hardin (1968); Elinor Ostrom (1990)','system',array['משאב משותף','מרחב ציבורי','כללים','קהילה']::text[]),
('broken-windows','תאוריית החלונות השבורים','Broken Windows Theory',array['עיר','חברה']::text[],'סימן גלוי של הזנחה, כמו חלון שבור שלא תוקן, משדר שאין משגיח ומזמין הזנחה נוספת.','הסביבה היא מסר על הנורמה. אנשים מתאימים את ההתנהגות למה שהם רואים סביבם. התאוריה שנויה במחלוקת: הראיות להשפעה על פשיעה חמורה חלשות.','[{"domain":"עיר","description":"פינה שמצטברת בה פסולת מושכת עוד פסולת, ופינה נקייה נשארת נקייה זמן רב יותר"},{"domain":"חברה","description":"בניסוי בהולנד, אנשים השליכו יותר עלונים לרצפה כשהקיר לידם היה מכוסה גרפיטי"},{"domain":"תרבות","description":"בקוד תוכנה, קובץ מוזנח אחד מוריד את הרף של כל מי שנוגע בו אחר כך"}]'::jsonb,2,array['eyes-on-the-street','social-contagion','information-cascade']::text[],'Wilson & Kelling (1982); Keizer, Lindenberg & Steg (2008)','system',array['הזנחה','נורמה','מרחב ציבורי','תחזוקה']::text[]),
('matthew-effect','אפקט מתיו','Matthew Effect',array['תרבות','חברה','כלכלה','מדע']::text[],'מי שיש לו יקבל עוד: יתרון ראשוני קטן מושך אליו משאבים והכרה, והפער גדל מעצמו.','יתרון מצטבר. תשומת לב, כסף וקשרים זורמים אל מי שכבר בולט, כי בולטות היא האות הזול ביותר לאיכות.','[{"domain":"תרבות","description":"מדען מפורסם מקבל את רוב הקרדיט על תגלית משותפת, ושיר שנכנס למצעד מושמע עוד"},{"domain":"עיר","description":"רחוב שכבר מצליח מושך אליו עוד עסקים, והרחוב הסמוך מתרוקן"},{"domain":"כלכלה","description":"הון מניב תשואה, והתשואה מגדילה את ההון"},{"domain":"מדע","description":"חוקר מוכר מקבל את רוב ההכרה על מאמר משותף, גם כשחוקר צעיר עשה את רוב העבודה"}]'::jsonb,4,array['pareto-principle','zipf-law','information-cascade','metcalfe-law']::text[],'Robert K. Merton (1968)','system',array['יתרון מצטבר','אי שוויון','הכרה','מוניטין']::text[]),
('parkinson-law','חוק פרקינסון','Parkinson''s Law',array['תרבות','כלכלה']::text[],'העבודה מתרחבת עד שהיא ממלאת את כל הזמן שהוקצה לה.','בלי אילוץ, המשימה מתנפחת: עוד בדיקות, עוד ישיבות ועוד שכבות. מנגנון שמייצר עבודה לעצמו גדל בלי קשר לכמות התפוקה.','[{"domain":"תרבות","description":"ישיבה שנקבעה לשעה נמשכת שעה, גם כשהנושא נסגר בעשר דקות"},{"domain":"עיר","description":"הליך רישוי שהוקצבו לו חודשים מתמלא בסבבי הערות עד המועד האחרון"},{"domain":"כלכלה","description":"ההוצאות עולות עד גובה ההכנסה"}]'::jsonb,3,array['induced-demand','brooks-law','goodhart-law']::text[],'C. Northcote Parkinson (1955), The Economist','system',array['זמן','ארגון','בירוקרטיה','אילוץ']::text[]),
('paradigm-shift','חוק שינוי הפרדיגמה','Paradigm Shift',array['מדע','תרבות']::text[],'המדע לא מתקדם בקו רציף. חריגות נערמות בשקט, עד שהתמונה כולה מתחלפת בבת אחת.','קהילה מדעית עובדת בתוך מסגרת מוסכמת, ודוחה חריגות כטעויות מדידה. כשהחריגות עוברות סף, המסגרת נכנסת למשבר, ודור חדש מאמץ מסגרת אחרת.','[{"domain":"מדע","description":"אלפרד וגנר הציע את נדידת היבשות ב-1912, והרעיון נדחה. רק בשנות ה-60, עם טקטוניקת הלוחות, הוא התקבל"},{"domain":"תרבות","description":"סגנון אמנותי נשאר שליט שנים אחרי שנשחק, ואז מתחלף בתוך עשור"},{"domain":"עיר","description":"תפיסת תכנון נשארת בתוקף גם כשהכשלים שלה נערמים, עד שדור חדש של מתכננים מחליף אותה"}]'::jsonb,3,array['information-cascade','minority-rule','chestertons-fence','file-drawer']::text[],'Thomas S. Kuhn, The Structure of Scientific Revolutions (1962)','system',array['פרדיגמה','מהפכה מדעית','חריגות','סף','דור']::text[]),
('multiple-discovery','חוק התגלית המרובה','Multiple Discovery',array['מדע','תרבות']::text[],'תגליות גדולות מתגלות לעתים קרובות פעמיים, בידי אנשים שלא ידעו זה על זה.','כשהידע, הכלים והשאלות כבר מונחים על השולחן של תקופה, כמה חוקרים מגיעים לאותו צעד בנפרד. התיאום בא מהסביבה המשותפת, ולא ממרכז שמכוון.','[{"domain":"מדע","description":"ניוטון ולייבניץ פיתחו את החשבון האינפיניטסימלי בנפרד. דרווין ווולאס הציגו את הברירה הטבעית יחד ב-1858"},{"domain":"כלכלה","description":"בל וגריי הגישו בקשות לפטנט על הטלפון באותו יום, 14 בפברואר 1876"},{"domain":"תרבות","description":"אותו רעיון עיצובי צץ בכמה סטודיואים באותה שנה, כי כולם ניזונים מאותם חומרים וכלים"}]'::jsonb,4,array['murmuration-law','schelling-point','conways-law','lotka-law']::text[],'Robert K. Merton, Singletons and Multiples in Scientific Discovery (1961); Ogburn & Thomas (1922)','system',array['תגלית','רוח הזמן','במקביל','המצאה','קרדיט']::text[]),
('team-size-law','חוק גודל הצוות','Small Teams Disrupt, Large Teams Develop',array['מדע','חברה']::text[],'צוותים קטנים פורצים כיוונים חדשים. צוותים גדולים מפתחים את מה שכבר ידוע.','כשצוות גדל, עולה מחיר התיאום, והוא נשען על רעיונות מבוססים שקל להסכים עליהם. צוות קטן יכול להמר על רעיון ישן או שולי, ולכן הוא זה שמשנה כיוון.','[{"domain":"מדע","description":"ניתוח של יותר מ-65 מיליון מאמרים, פטנטים ומוצרי תוכנה מהשנים 1954 עד 2014 מצא את הדפוס בכל התחומים"},{"domain":"חברה","description":"ועדה גדולה מגיעה לנוסח שכולם יכולים לחיות איתו, ולא לנוסח הנועז"},{"domain":"עיר","description":"צוות תכנון קטן מעז להציע רחוב אחר לגמרי, וצוות גדול משפר את הרחוב הקיים"}]'::jsonb,4,array['brooks-law','dunbar-number','urban-scaling','eroom-law']::text[],'Wu, Wang & Evans, Nature (2019)','system',array['צוות','גודל','חדשנות','שיבוש','תיאום']::text[]),
('eroom-law','חוק ארום','Eroom''s Law',array['מדע','כלכלה']::text[],'מספר התרופות החדשות לכל מיליארד דולר של מחקר ופיתוח ירד בחצי בערך כל 9 שנים, מאז 1950.','התגליות הקלות נקטפו ראשונות. כל תרופה חדשה צריכה לנצח את כל הקודמות, והרף הרגולטורי עולה. ההשקעה גדלה, והתפוקה לכל שקל יורדת.','[{"domain":"מדע","description":"השם הוא \"מור\" בהיפוך אותיות: שבבים הוכפלו בכוחם כל שנתיים, ופיתוח תרופות התייקר באותו קצב"},{"domain":"ספורט","description":"שבירת שיא עולם דורשת היום הרבה יותר משאבים מבעבר, והשיפור קטן יותר"},{"domain":"כלכלה","description":"שדה נפט או מכרה מניבים פחות ככל שמעמיקים, כי העתודות הנגישות נוצלו קודם"}]'::jsonb,4,array['diminishing-returns','human-performance-ceiling','parkinson-law','team-size-law']::text[],'Scannell, Blanckley, Boldon & Warrington, Nature Reviews Drug Discovery (2012)','system',array['מחקר ופיתוח','תרופות','תפוקה','תקרה','עלות']::text[]),
('lotka-law','חוק לוטקה','Lotka''s Law',array['מדע','תרבות']::text[],'מעט חוקרים כותבים את רוב המאמרים. מספר הכותבים של n מאמרים קטן בערך לפי n בריבוע.','פרסום מוליד פרסום. מי שכבר פרסם מקבל מימון, שותפים וניסיון, ולכן מפרסם שוב. רוב הכותבים נעצרים אחרי מאמר אחד, ומיעוט קטן ממשיך בלי סוף.','[{"domain":"מדע","description":"בנתונים של לוטקה מ-1926, כ-60% מהכותבים פרסמו מאמר אחד בלבד"},{"domain":"תרבות","description":"מעט יוצרים אחראים לרוב היצירות שנשארות בזיכרון של תחום"},{"domain":"חברה","description":"בקהילה מקוונת, מעט משתתפים כותבים את רוב התוכן, והרוב קוראים בלבד"}]'::jsonb,4,array['zipf-law','pareto-principle','matthew-effect','multiple-discovery']::text[],'Alfred J. Lotka, Journal of the Washington Academy of Sciences (1926)','system',array['פרסומים','פריון','חוק חזקה','ריכוז','מיעוט']::text[]),
('file-drawer','חוק המגירה','File Drawer Problem',array['מדע','חברה']::text[],'ניסויים שלא מצאו דבר נשארים במגירה. לכן הספרות המדעית נראית בטוחה יותר ממה שהיא באמת.','לכל חוקר משתלם לפרסם רק תוצאה חיובית, כי רק היא מתקבלת לכתב עת. כל החלטה כזו הגיונית לבדה, אבל יחד הן מעוותות את הידע של כולם.','[{"domain":"מדע","description":"ב-74 ניסויים של נוגדי דיכאון, הספרות המפורסמת הציגה 94% הצלחה. לפי נתוני ה-FDA, רק 51% היו חיוביים"},{"domain":"חברה","description":"ארגון מדווח על הפרויקטים שהצליחו, והכישלונות לא נכנסים לדוח השנתי"},{"domain":"עיר","description":"עיר מציגה את הרחוב שהתחדש בהצלחה, והפיילוטים שנכשלו לא מתועדים, כך שהעיר הבאה חוזרת עליהם"}]'::jsonb,4,array['goodhart-law','tragedy-of-commons','paradigm-shift']::text[],'Robert Rosenthal, Psychological Bulletin (1979); Turner et al., NEJM (2008)','system',array['הטיית פרסום','תוצאה שלילית','שחזור','תמריץ','ידע']::text[])
